const SPRITE_ROLLEN = ['figur','hindernis_1','hindernis_2','hindernis_3','belohnung',
                      'leben','richtung','ziel','gegner','helfer'];

// <img>-Tag für eine Rolle aus einem Paket. Längere Kante = size (px).
function spriteBild(paketSchluessel, rolle, size, cls){
  const p = SPRITE_PAKETE[paketSchluessel]; if(!p) return '';
  const s = p.sprites[rolle]; if(!s) return '';
  const w = s.w >= s.h ? size : Math.round(size * s.w / s.h);
  const h = s.h >= s.w ? size : Math.round(size * s.h / s.w);
  const stil = p.stil === 'pixel' ? 'image-rendering:pixelated;' : '';
  return '<img class="' + (cls||'') + '" alt="" width="' + w + '" height="' + h
       + '" style="display:block;' + stil + '" src="' + s.src + '">';
}

if (typeof window !== 'undefined'){
  window.SPRITE_PAKETE = SPRITE_PAKETE;
  window.SPRITE_ROLLEN = SPRITE_ROLLEN;
  window.spriteBild = spriteBild;
}
if (typeof module !== 'undefined') module.exports = { SPRITE_PAKETE, SPRITE_ROLLEN, spriteBild };
